python3 << 'EOF'
import bioblend.galaxy

api_key = "[REDACTED_GALAXY_API_KEY]"
gi = bioblend.galaxy.GalaxyInstance(url="https://usegalaxy.org", key=api_key)

history_id = "bbd44e69cb8906b50d1897517f571caf"

# Try using BioBlend to submit DESeq2 directly
tool_id = "toolshed.g2.bx.psu.edu/repos/iuc/deseq2/deseq2/2.11.40.8+galaxy3"

# Legacy format inputs
inputs = {
    "select_data|how": "datasets_per_level",
    "select_data|rep_factorName_0|factorName": "condition",
    "select_data|rep_factorName_0|rep_factorLevel_0|factorLevel": "KL",
    "select_data|rep_factorName_0|rep_factorLevel_0|countsFile": {
        "src": "hda", 
        "id": "f9cad7b01a472135c62f8c6bb4194f08"
    },
    "select_data|rep_factorName_0|rep_factorLevel_1|factorLevel": "WL",
    "select_data|rep_factorName_0|rep_factorLevel_1|countsFile": {
        "src": "hda",
        "id": "f9cad7b01a4721350f6aaaf7af6b6582"
    },
    "header": "Yes",
    "tximport|tximport_selector": "count",
    "advanced_options|lfc_shrinkage_type": "apeglm",
    "output_options|output_selector": "pdf",
    "output_options|alpha_ma": "0.1"
}

try:
    result = gi.tools.run_tool(history_id, tool_id, inputs)
    print(f"Submitted! Job info: {result}")
    if 'jobs' in result:
        for job in result['jobs']:
            print(f"Job ID: {job['id']}, State: {job.get('state', 'unknown')}")
    if 'outputs' in result:
        for out in result['outputs']:
            print(f"Output: {out['id']} - {out['name']}")
except Exception as e:
    print(f"Error: {e}")
EOF

